statements:
CREATE TABLE rer_portability_journal (
  source TEXT NOT NULL, tombstone TEXT NOT NULL, PRIMARY KEY(source,tombstone)
)

CREATE TABLE IF NOT EXISTS integration_attempts (
 namespace TEXT NOT NULL, id TEXT NOT NULL, delivery_id TEXT NOT NULL, number INTEGER NOT NULL,
 started_at INTEGER NOT NULL, finished_at INTEGER, outcome TEXT,
 PRIMARY KEY(namespace,id), UNIQUE(namespace,delivery_id,number)
)

CREATE TABLE IF NOT EXISTS integration_resolutions (
 namespace TEXT NOT NULL, id TEXT NOT NULL, delivery_id TEXT NOT NULL, at INTEGER NOT NULL, outcome TEXT NOT NULL,
 PRIMARY KEY(namespace,id)
)

CREATE TABLE IF NOT EXISTS integration_replays (
 namespace TEXT NOT NULL, id TEXT NOT NULL, fingerprint TEXT NOT NULL, envelope TEXT NOT NULL, received_at INTEGER NOT NULL,
 PRIMARY KEY(namespace,id)
)

CREATE TABLE IF NOT EXISTS integration_tokens (
 namespace TEXT NOT NULL, id TEXT NOT NULL, token_hash TEXT NOT NULL, name TEXT NOT NULL, scopes TEXT NOT NULL,
 created_at INTEGER NOT NULL, expires_at INTEGER, revoked_at INTEGER,
 PRIMARY KEY(namespace,id), UNIQUE(namespace,token_hash)
)

CREATE TABLE IF NOT EXISTS integration_token_usage (
 namespace TEXT NOT NULL, id TEXT NOT NULL, token_id TEXT, at INTEGER NOT NULL, required_scopes TEXT NOT NULL, allowed INTEGER NOT NULL,
 request_id TEXT, resource TEXT,
 PRIMARY KEY(namespace,id)
)

CREATE TABLE IF NOT EXISTS integration_token_events (
 namespace TEXT NOT NULL, id TEXT NOT NULL, token_id TEXT NOT NULL, at INTEGER NOT NULL,
 action TEXT NOT NULL, feature TEXT NOT NULL,
 PRIMARY KEY(namespace,id)
)

CREATE TABLE IF NOT EXISTS ik_original_sets (
 job_id TEXT PRIMARY KEY REFERENCES ik_jobs(id), version INTEGER NOT NULL
)

CREATE TABLE IF NOT EXISTS oa_auth_settings (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), idp_sign_in INTEGER NOT NULL CHECK(idp_sign_in IN (0,1)), generation INTEGER NOT NULL DEFAULT 0, first_setup INTEGER NOT NULL DEFAULT 0
)

CREATE TABLE IF NOT EXISTS oa_auth_audit (
 id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, value TEXT NOT NULL, created_at INTEGER NOT NULL
)

CREATE TABLE IF NOT EXISTS oa_provider_sessions (
 session_id TEXT PRIMARY KEY, issuer TEXT NOT NULL, subject TEXT NOT NULL, sid TEXT, generation INTEGER NOT NULL
)

CREATE TABLE IF NOT EXISTS oa_logout_events (
 issuer TEXT NOT NULL, jti TEXT NOT NULL, consumed_at INTEGER NOT NULL CHECK(consumed_at>=0), PRIMARY KEY(issuer,jti)
)

CREATE TRIGGER IF NOT EXISTS oa_first_setup_provider_setting AFTER INSERT ON oa_bootstrap BEGIN
 INSERT INTO oa_auth_settings(singleton,idp_sign_in,generation,first_setup) VALUES(1,0,0,1) ON CONFLICT DO NOTHING;
END

CREATE TABLE rer_erasure_blobs (
  operation TEXT NOT NULL, bucket TEXT NOT NULL, key TEXT NOT NULL, PRIMARY KEY(operation,bucket,key)
)

CREATE TABLE IF NOT EXISTS rer_dependency_installation (
 singleton INTEGER PRIMARY KEY CHECK(singleton=1), sector_id TEXT NOT NULL UNIQUE
)

CREATE TABLE IF NOT EXISTS rer_dependency_pending (
 interface TEXT PRIMARY KEY, issuer TEXT NOT NULL, approved_by TEXT NOT NULL, expires_at INTEGER NOT NULL, approved_session TEXT NOT NULL, approved_version INTEGER NOT NULL, callbacks TEXT NOT NULL
)

CREATE TABLE IF NOT EXISTS rer_dependency_codes (
 digest TEXT PRIMARY KEY, created_at INTEGER NOT NULL CHECK(created_at>=0)
)

CREATE TRIGGER IF NOT EXISTS oa_native_claim_closes_provider_setup AFTER INSERT ON oa_sessions
WHEN NEW.kind='native' AND NOT EXISTS(SELECT 1 FROM oa_sessions WHERE operator_id=NEW.operator_id AND id!=NEW.id) AND EXISTS(SELECT 1 FROM oa_bootstrap WHERE claim_id=NEW.operator_id AND claimed_at=NEW.created_at)
BEGIN
 UPDATE oa_auth_settings SET first_setup=0 WHERE singleton=1 AND NOT EXISTS(
  SELECT 1 FROM oa_setup_links WHERE interface='oidc-provider@1' AND completed=0 AND owner_id IS NULL AND expires_at>NEW.created_at
 );
 UPDATE oa_setup_links SET owner_id=NEW.operator_id,owner_version=NEW.operator_version,session_id=NEW.id
 WHERE owner_id IS NULL AND completed=0 AND expires_at>NEW.created_at;
END

CREATE TABLE IF NOT EXISTS oc_idp_grants (
 issuer TEXT NOT NULL, client_id TEXT NOT NULL, jti TEXT NOT NULL, subject TEXT NOT NULL, sector_id TEXT NOT NULL,
 PRIMARY KEY(issuer,client_id), UNIQUE(issuer,jti)
);

-- Older cached keys included build metadata and did not preserve every semver
-- prerelease ordering. Runtime reindexes keys before reading/comparing releases.
UPDATE release_metadata SET version_key=NULL;

CREATE TRIGGER audit_journal_fact AFTER INSERT ON audit BEGIN
 SELECT RAISE(ABORT,'audit_context_required') WHERE NOT EXISTS(SELECT 1 FROM audit_context);
 UPDATE audit_context SET committed=1;
END

CREATE TRIGGER audit_restore_commit AFTER UPDATE OF import_job ON rer_portability_state WHEN OLD.import_job IS NOT NULL AND NEW.import_job IS NULL BEGIN
 INSERT OR IGNORE INTO spool_audit_events(id,created,source,actor_kind,actor_label,action,subject_kind,subject_label,project_label,outcome,status)
  SELECT json_extract(fact,'$.id'),json_extract(fact,'$.created'),json_extract(fact,'$.source'),json_extract(fact,'$.actor_kind'),json_extract(fact,'$.actor_label'),
   json_extract(fact,'$.action'),json_extract(fact,'$.subject_kind'),json_extract(fact,'$.subject_label'),json_extract(fact,'$.project_label'),json_extract(fact,'$.outcome'),json_extract(fact,'$.status')
  FROM audit_restore_staging WHERE OLD.applying=1 AND import_id=OLD.import_job AND ord>0 ORDER BY ord;

 INSERT INTO audit_legacy_labels SELECT project,'audit:'||lower(hex(randomblob(16))) FROM (SELECT DISTINCT project FROM audit WHERE project IS NOT NULL)
  WHERE OLD.applying=1 AND NOT EXISTS(SELECT 1 FROM audit_restore_staging WHERE import_id=OLD.import_job);
 INSERT INTO spool_audit_events(id,created,source,actor_kind,actor_label,action,subject_kind,subject_label,project_label,outcome,status)
  SELECT lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(6))),
   a.created,'legacy','unknown','audit:'||lower(hex(randomblob(16))),COALESCE(m.action,'private.action'),COALESCE(m.subject_kind,'unknown'),'audit:'||lower(hex(randomblob(16))),
   (SELECT label FROM audit_legacy_labels l WHERE l.project=a.project),'succeeded',NULL
  FROM audit a LEFT JOIN audit_legacy_actions m ON m.kind=a.kind
  WHERE OLD.applying=1 AND NOT EXISTS(SELECT 1 FROM audit_restore_staging WHERE import_id=OLD.import_job) ORDER BY a.created,a.id;
 DELETE FROM audit_legacy_labels;

 UPDATE audit_context SET committed=1 WHERE OLD.applying=1;
 INSERT INTO spool_audit_events(id,created,source,actor_kind,actor_label,action,subject_kind,subject_label,project_label,outcome,status)
  SELECT lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(6))),
   CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),'service','service',label,'archive.restore','installation','audit:'||lower(hex(randomblob(16))),NULL,'succeeded',NULL
  FROM audit_actor_links WHERE OLD.applying=1 AND NOT EXISTS(SELECT 1 FROM audit_context) AND kind='service' AND lookup_hash='d832ceb4065065973b7c2718944b0047cd6672ae8d3279b42c0771af1cfa367a';
 DELETE FROM audit_restore_staging WHERE import_id=OLD.import_job;
END

CREATE TRIGGER release_dist_restore AFTER UPDATE OF import_job ON rer_portability_state WHEN OLD.import_job IS NOT NULL AND NEW.import_job IS NULL AND OLD.applying=1 BEGIN
 UPDATE events SET build='[sentry:no-dist]',payload=json_set(payload,'$.build','[sentry:no-dist]') WHERE build='sentry-no-dist' AND json_type(payload,'$.sentry')='object' AND json_extract(payload,'$.sentry.dist') IS NULL;
 INSERT INTO release_builds(project,release,build,registered) SELECT DISTINCT e.project,e.release,e.build,0 FROM events e JOIN releases r ON r.project=e.project AND r.name=e.release WHERE e.build='[sentry:no-dist]' ON CONFLICT DO NOTHING;
 UPDATE releases SET build='[sentry:no-dist]' WHERE build='sentry-no-dist' AND EXISTS(SELECT 1 FROM events e WHERE e.project=releases.project AND e.release=releases.name AND e.build='[sentry:no-dist]') AND NOT EXISTS(SELECT 1 FROM events e WHERE e.project=releases.project AND e.release=releases.name AND e.build='sentry-no-dist') AND NOT EXISTS(SELECT 1 FROM artifacts a WHERE a.project=releases.project AND a.release=releases.name AND a.build='sentry-no-dist') AND NOT EXISTS(SELECT 1 FROM deployment_path_mappings m WHERE m.project=releases.project AND m.release=releases.name AND m.build='sentry-no-dist');
 DELETE FROM release_builds WHERE build='sentry-no-dist' AND registered=0 AND NOT EXISTS(SELECT 1 FROM events e WHERE e.project=release_builds.project AND e.release=release_builds.release AND e.build=release_builds.build) AND NOT EXISTS(SELECT 1 FROM releases r WHERE r.project=release_builds.project AND r.name=release_builds.release AND r.build=release_builds.build) AND NOT EXISTS(SELECT 1 FROM artifacts a WHERE a.project=release_builds.project AND a.release=release_builds.release AND a.build=release_builds.build) AND NOT EXISTS(SELECT 1 FROM alerts a WHERE a.project=release_builds.project AND json_extract(a.payload,'$.release.name')=release_builds.release AND json_extract(a.payload,'$.release.build')=release_builds.build);
END

CREATE TABLE follow_up_feed_custody (
 alert TEXT PRIMARY KEY REFERENCES alerts(id),project TEXT NOT NULL REFERENCES projects(id)
)

INSERT INTO short_id_prefixes(prefix,project,next,created)
 SELECT CASE WHEN position=1 THEN base ELSE base||'_'||position END,id,1,created FROM (
  SELECT id,created,base,ROW_NUMBER() OVER (PARTITION BY base ORDER BY created,id) position FROM (
   SELECT id,created,COALESCE(NULLIF(trim(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(upper(id),'.','-'),':','-'),'_','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'--','-'),'-'),''),'P') base FROM projects));
INSERT INTO issue_short_ids(short_id,project,issue,assigned,number,created)
 SELECT p.prefix||'-'||(CASE WHEN (m.n)>=1073741824 THEN substr('0123456789ABCDEFGHJKMNPQRSTVWXYZ',((m.n)/1073741824)%32+1,1) ELSE '' END||CASE WHEN (m.n)>=33554432 THEN substr('0123456789ABCDEFGHJKMNPQRSTVWXYZ',((m.n)/33554432)%32+1,1) ELSE '' END||CASE WHEN (m.n)>=1048576 THEN substr('0123456789ABCDEFGHJKMNPQRSTVWXYZ',((m.n)/1048576)%32+1,1) ELSE '' END||CASE WHEN (m.n)>=32768 THEN substr('0123456789ABCDEFGHJKMNPQRSTVWXYZ',((m.n)/32768)%32+1,1) ELSE '' END||CASE WHEN (m.n)>=1024 THEN substr('0123456789ABCDEFGHJKMNPQRSTVWXYZ',((m.n)/1024)%32+1,1) ELSE '' END||CASE WHEN (m.n)>=32 THEN substr('0123456789ABCDEFGHJKMNPQRSTVWXYZ',((m.n)/32)%32+1,1) ELSE '' END||substr('0123456789ABCDEFGHJKMNPQRSTVWXYZ',(m.n)%32+1,1)),m.project,m.id,m.id,m.n,m.first_seen
 FROM (SELECT id,project,first_seen,ROW_NUMBER() OVER (PARTITION BY project ORDER BY first_seen,id) n FROM issues) m JOIN short_id_prefixes p ON p.project=m.project;
UPDATE short_id_prefixes SET next=COALESCE((SELECT MAX(number) FROM issue_short_ids WHERE project=short_id_prefixes.project),0)+1;

CREATE TABLE spool_organizations (
 id TEXT PRIMARY KEY, name TEXT NOT NULL, created INTEGER NOT NULL
)

CREATE TRIGGER spool_member_accept AFTER UPDATE OF status ON oa_operators WHEN NEW.status='active' AND OLD.status='invited' BEGIN
 UPDATE spool_member_invites SET state='accepted' WHERE state='invited' AND member IN (SELECT id FROM spool_members WHERE operator_id=NEW.id AND state='active');
END

CREATE TRIGGER audit_restore_commit AFTER UPDATE OF import_job ON rer_portability_state WHEN OLD.import_job IS NOT NULL AND NEW.import_job IS NULL BEGIN
 INSERT OR IGNORE INTO spool_audit_events(id,created,source,actor_kind,actor_label,action,subject_kind,subject_label,project_label,outcome,status)
  SELECT json_extract(fact,'$.id'),json_extract(fact,'$.created'),json_extract(fact,'$.source'),json_extract(fact,'$.actor_kind'),json_extract(fact,'$.actor_label'),
   json_extract(fact,'$.action'),json_extract(fact,'$.subject_kind'),json_extract(fact,'$.subject_label'),json_extract(fact,'$.project_label'),json_extract(fact,'$.outcome'),json_extract(fact,'$.status')
  FROM audit_restore_staging WHERE OLD.applying=1 AND import_id=OLD.import_job AND ord>0 ORDER BY ord;

 INSERT INTO audit_legacy_labels SELECT project,'audit:'||lower(hex(randomblob(16))) FROM (SELECT DISTINCT project FROM audit WHERE project IS NOT NULL)
  WHERE OLD.applying=1 AND NOT EXISTS(SELECT 1 FROM audit_restore_staging WHERE import_id=OLD.import_job);
 INSERT INTO spool_audit_events(id,created,source,actor_kind,actor_label,action,subject_kind,subject_label,project_label,outcome,status)
  SELECT lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(6))),
   a.created,'legacy','unknown','audit:'||lower(hex(randomblob(16))),COALESCE(m.action,'private.action'),COALESCE(m.subject_kind,'unknown'),'audit:'||lower(hex(randomblob(16))),
   (SELECT label FROM audit_legacy_labels l WHERE l.project=a.project),'succeeded',NULL
  FROM audit a LEFT JOIN audit_legacy_actions m ON m.kind=a.kind
  WHERE OLD.applying=1 AND NOT EXISTS(SELECT 1 FROM audit_restore_staging WHERE import_id=OLD.import_job) ORDER BY a.created,a.id;
 DELETE FROM audit_legacy_labels;

 UPDATE audit_context SET committed=1 WHERE OLD.applying=1;
 INSERT INTO spool_audit_events(id,created,source,actor_kind,actor_label,action,subject_kind,subject_label,project_label,outcome,status)
  SELECT lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(2)))||'-'||lower(hex(randomblob(6))),
   CAST((julianday('now')-2440587.5)*86400000 AS INTEGER),'service','service',label,'archive.restore','installation','audit:'||lower(hex(randomblob(16))),NULL,'succeeded',NULL
  FROM audit_actor_links WHERE OLD.applying=1 AND NOT EXISTS(SELECT 1 FROM audit_context) AND kind='service' AND lookup_hash='d832ceb4065065973b7c2718944b0047cd6672ae8d3279b42c0771af1cfa367a';
 DELETE FROM audit_restore_staging WHERE import_id=OLD.import_job;
END

CREATE TRIGGER spool_reporting_view_removed AFTER DELETE ON review_views BEGIN
 DELETE FROM spool_reporting_widgets WHERE project=OLD.project AND view_id=OLD.id;
END

CREATE TRIGGER issue_priority_regression AFTER UPDATE OF state ON issues WHEN OLD.state='resolved' AND NEW.state='open' BEGIN
 UPDATE issue_priorities SET automatic=3 WHERE project=NEW.project AND issue=NEW.id;
END

CREATE TRIGGER issue_activity_state AFTER UPDATE OF state ON issues
WHEN OLD.state<>NEW.state AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL)
BEGIN
 INSERT INTO issue_activity SELECT lower(hex(randomblob(16))),NEW.project,NEW.id,
 CASE WHEN OLD.state='resolved' AND NEW.state='open' AND COALESCE((SELECT action FROM audit_context),'') IN ('capture.native','capture.sentry','capture.otlp') THEN 'regression' ELSE 'state' END,
 CASE WHEN EXISTS(SELECT 1 FROM audit_context WHERE action IN ('capture.native','capture.sentry','capture.otlp')) THEN 'ingest' ELSE COALESCE((SELECT actor_kind FROM audit_context),'service') END,COALESCE((SELECT actor_label FROM audit_context),'audit:'||lower(hex(randomblob(16)))),json_object('from',OLD.state,'state',NEW.state),CAST((julianday('now')-2440587.5)*86400000 AS INTEGER);
END;
CREATE TABLE issue_comments (
 id TEXT PRIMARY KEY,project TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,issue TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
 operator_id TEXT NOT NULL,actor_kind TEXT NOT NULL,actor_label TEXT NOT NULL,
 body TEXT NOT NULL CHECK(length(body)<=4000),mentions TEXT NOT NULL DEFAULT '[]' CHECK(json_valid(mentions)),
 version INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL,updated INTEGER NOT NULL
);
CREATE INDEX issue_comments_order ON issue_comments(project,issue,created,id);
CREATE TRIGGER issue_comments_capacity BEFORE INSERT ON issue_comments
WHEN (SELECT count(*) FROM issue_comments WHERE project=NEW.project AND issue=NEW.issue)>=200
BEGIN SELECT RAISE(ABORT,'issue_comment_limit'); END;
CREATE TABLE issue_subscriptions (
 project TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,issue TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,operator_id TEXT NOT NULL,
 reason TEXT NOT NULL CHECK(reason IN ('comment','mention','manual')),
 state TEXT NOT NULL CHECK(state IN ('subscribed','unsubscribed','inert')),updated INTEGER NOT NULL,
 PRIMARY KEY(project,issue,operator_id,reason)
);
CREATE TABLE recurrence_policies (
 project TEXT PRIMARY KEY REFERENCES projects(id) ON DELETE CASCADE,revision INTEGER NOT NULL CHECK(revision>=1),
 reopen_same_release INTEGER NOT NULL DEFAULT 0 CHECK(reopen_same_release IN(0,1)),updated INTEGER NOT NULL
);
CREATE TRIGGER issue_activity_resolution AFTER UPDATE OF mode,boundary_seq ON issue_resolutions
WHEN EXISTS(SELECT 1 FROM issues WHERE id=NEW.issue AND state='resolved') AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL)
BEGIN
 INSERT INTO issue_activity SELECT lower(hex(randomblob(16))),NEW.project,NEW.issue,'resolution',
 COALESCE((SELECT actor_kind FROM audit_context),'service'),COALESCE((SELECT actor_label FROM audit_context),'audit:'||lower(hex(randomblob(16)))),
 json_object('mode',NEW.mode,'release',(SELECT name FROM releases WHERE project=NEW.project AND seq=NEW.boundary_seq)),NEW.updated;
END;
CREATE TRIGGER issue_activity_same_release AFTER UPDATE OF count ON issues
WHEN OLD.state='resolved' AND NEW.count>OLD.count AND EXISTS(SELECT 1 FROM audit_context WHERE action IN ('capture.native','capture.sentry','capture.otlp')) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL)
BEGIN
 INSERT INTO issue_activity SELECT lower(hex(randomblob(16))),NEW.project,NEW.id,'resolved_release_recurrence',
 'ingest',COALESCE((SELECT actor_label FROM audit_context),'audit:'||lower(hex(randomblob(16)))),
 json_object('release',e.release,'count',1),e.received
 FROM events e JOIN issue_resolutions r ON r.project=NEW.project AND r.issue=NEW.id
 WHERE e.rowid=(SELECT rowid FROM events WHERE project=NEW.project AND issue=NEW.id ORDER BY rowid DESC LIMIT 1)
 AND (r.mode='current' OR r.mode='named' AND EXISTS(SELECT 1 FROM issue_recurrence_boundaries snapshot WHERE snapshot.project=NEW.project AND snapshot.issue=NEW.id AND snapshot.boundary_seq=r.boundary_seq AND snapshot.seen_at_resolution=1)) AND e.release<>'' AND e.release_seq=COALESCE(r.boundary_seq,OLD.resolved_seq)
 AND NOT EXISTS(SELECT 1 FROM event_suppressions x WHERE x.project=e.project AND x.event=e.id AND x.occurrence=e.occurrence);
END;
UPDATE issue_priorities SET automatic=3 WHERE issue IN (SELECT issue FROM alerts WHERE kind IN ('regression','spike'));
CREATE TRIGGER issue_priority_escalation AFTER INSERT ON alerts WHEN NEW.kind IN ('regression','spike')
AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL)
BEGIN
 UPDATE issues SET revision=revision+1 WHERE id=NEW.issue AND project=NEW.project AND EXISTS(SELECT 1 FROM issue_priorities p WHERE p.issue=NEW.issue AND p.automatic<3 AND p.manual IS NULL);
 UPDATE issue_priorities SET automatic=3 WHERE project=NEW.project AND issue=NEW.issue;
END;

CREATE TRIGGER issue_activity_old_release AFTER UPDATE OF count ON issues
WHEN OLD.state='resolved' AND NEW.count>OLD.count AND EXISTS(SELECT 1 FROM audit_context WHERE action IN ('capture.native','capture.sentry','capture.otlp')) AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL)
BEGIN
 INSERT INTO issue_activity SELECT lower(hex(randomblob(16))),NEW.project,NEW.id,'older_release_recurrence',
 'ingest',COALESCE((SELECT actor_label FROM audit_context),'audit:'||lower(hex(randomblob(16)))),json_object('release',incoming.release,'count',1),incoming.received
 FROM events incoming JOIN issues i ON i.id=NEW.id AND i.project=NEW.project
 WHERE incoming.rowid=(SELECT rowid FROM events WHERE project=NEW.project AND issue=NEW.id ORDER BY rowid DESC LIMIT 1)
 AND (incoming.release<>'' AND incoming.release_seq<>COALESCE((SELECT boundary_seq FROM issue_resolutions resolution WHERE resolution.project=i.project AND resolution.issue=i.id),i.resolved_seq) AND EXISTS(SELECT 1 FROM releases boundary_release WHERE boundary_release.project=i.project AND boundary_release.seq=COALESCE((SELECT boundary_seq FROM issue_resolutions resolution WHERE resolution.project=i.project AND resolution.issue=i.id),i.resolved_seq)) AND EXISTS(SELECT 1 FROM issue_resolutions resolution WHERE resolution.project=i.project AND resolution.issue=i.id AND resolution.mode IN ('current','next','named')) AND NOT (incoming.release<>'' AND CASE WHEN COALESCE((SELECT boundary_seq FROM issue_resolutions resolution WHERE resolution.project=i.project AND resolution.issue=i.id),i.resolved_seq) IS NULL OR COALESCE((SELECT boundary_seq FROM issue_resolutions resolution WHERE resolution.project=i.project AND resolution.issue=i.id),i.resolved_seq)=0 THEN 1
 WHEN json_extract(incoming.payload,'$.sentry') IS NULL OR COALESCE((SELECT json_extract(policy,'$.order') FROM release_policies WHERE project=i.project),'sentry')='registered' THEN incoming.release_seq>COALESCE((SELECT boundary_seq FROM issue_resolutions resolution WHERE resolution.project=i.project AND resolution.issue=i.id),i.resolved_seq)
 ELSE EXISTS(SELECT 1 FROM releases candidate_release JOIN releases boundary_release ON boundary_release.project=candidate_release.project AND boundary_release.seq=COALESCE((SELECT boundary_seq FROM issue_resolutions resolution WHERE resolution.project=i.project AND resolution.issue=i.id),i.resolved_seq) WHERE candidate_release.project=i.project AND candidate_release.name=incoming.release AND (CASE WHEN COALESCE((SELECT json_extract(policy,'$.order') FROM release_policies WHERE project=i.project),'sentry')='registered' THEN candidate_release.seq ELSE 0 END,CASE WHEN COALESCE((SELECT json_extract(policy,'$.order') FROM release_policies WHERE project=i.project),'sentry')='semver' AND (SELECT version_key FROM release_order_keys WHERE project=candidate_release.project AND release=candidate_release.name) IS NULL THEN 1 ELSE 0 END,(CASE WHEN COALESCE((SELECT json_extract(policy,'$.order') FROM release_policies WHERE project=i.project),'sentry')='semver' THEN COALESCE((SELECT version_key FROM release_order_keys WHERE project=candidate_release.project AND release=candidate_release.name),'') ELSE '' END) COLLATE BINARY,CASE WHEN COALESCE((SELECT json_extract(policy,'$.order') FROM release_policies WHERE project=i.project),'sentry')='registered' THEN 0 ELSE COALESCE((SELECT first_seen FROM release_metadata WHERE project=candidate_release.project AND release=candidate_release.name),candidate_release.created) END,candidate_release.name COLLATE BINARY)>(CASE WHEN COALESCE((SELECT json_extract(policy,'$.order') FROM release_policies WHERE project=i.project),'sentry')='registered' THEN boundary_release.seq ELSE 0 END,CASE WHEN COALESCE((SELECT json_extract(policy,'$.order') FROM release_policies WHERE project=i.project),'sentry')='semver' AND (SELECT version_key FROM release_order_keys WHERE project=boundary_release.project AND release=boundary_release.name) IS NULL THEN 1 ELSE 0 END,(CASE WHEN COALESCE((SELECT json_extract(policy,'$.order') FROM release_policies WHERE project=i.project),'sentry')='semver' THEN COALESCE((SELECT version_key FROM release_order_keys WHERE project=boundary_release.project AND release=boundary_release.name),'') ELSE '' END) COLLATE BINARY,CASE WHEN COALESCE((SELECT json_extract(policy,'$.order') FROM release_policies WHERE project=i.project),'sentry')='registered' THEN 0 ELSE COALESCE((SELECT first_seen FROM release_metadata WHERE project=boundary_release.project AND release=boundary_release.name),boundary_release.created) END,boundary_release.name COLLATE BINARY)) END))
 AND NOT EXISTS(SELECT 1 FROM event_suppressions x WHERE x.project=incoming.project AND x.event=incoming.id AND x.occurrence=incoming.occurrence);
END;
CREATE TABLE issue_suppressions (
 id TEXT PRIMARY KEY,project TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,issue TEXT NOT NULL REFERENCES issues(id) ON DELETE CASCADE,
 mode TEXT NOT NULL CHECK(mode IN('forever','until','count','users','escalating','snooze')),reason TEXT NOT NULL,
 deadline INTEGER,occurrence_target INTEGER,user_target INTEGER,window_ms INTEGER,forecast REAL,
 started INTEGER NOT NULL,state TEXT NOT NULL CHECK(state IN('active','expired','ended')),ended INTEGER,
 historical INTEGER NOT NULL DEFAULT 0 CHECK(historical IN(0,1)),observed_count INTEGER NOT NULL DEFAULT 0 CHECK(observed_count>=0)
);
CREATE UNIQUE INDEX issue_suppressions_active ON issue_suppressions(project,issue) WHERE state='active' AND historical=0;
CREATE TRIGGER issue_suppression_ended AFTER UPDATE OF state ON issues WHEN OLD.state='suppressed' AND NEW.state<>'suppressed'
BEGIN
 UPDATE issue_suppressions SET state='ended',ended=CAST((julianday('now')-2440587.5)*86400000 AS INTEGER)
 WHERE project=NEW.project AND issue=NEW.id AND state='active' AND historical=0;
END;
CREATE TRIGGER issue_suppression_escalation AFTER UPDATE OF state ON issue_suppressions
WHEN OLD.state='active' AND NEW.state='expired' AND NEW.mode='escalating' AND NEW.historical=0
BEGIN
 UPDATE issue_priorities SET automatic=3 WHERE project=NEW.project AND issue=NEW.issue;
END;
CREATE TRIGGER issue_priority_regroup AFTER UPDATE OF issue ON events WHEN OLD.issue<>NEW.issue
AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL)
BEGIN
 UPDATE issue_priorities SET automatic=MAX(automatic,CASE COALESCE(json_extract(NEW.payload,'$.sentry.level'),'error') WHEN 'fatal' THEN 3 WHEN 'error' THEN 3 WHEN 'warning' THEN 2 ELSE 1 END) WHERE project=NEW.project AND issue=NEW.issue;
END;



CREATE TABLE issue_recurrence_boundaries (
 project TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,issue TEXT PRIMARY KEY REFERENCES issues(id) ON DELETE CASCADE,
 boundary_seq INTEGER,seen_at_resolution INTEGER NOT NULL CHECK(seen_at_resolution IN (0,1))
);
CREATE TRIGGER issue_recurrence_boundary_update AFTER UPDATE OF mode,boundary_seq ON issue_resolutions
WHEN EXISTS(SELECT 1 FROM issues WHERE id=NEW.issue AND state='resolved')
AND NOT EXISTS(SELECT 1 FROM rer_portability_state WHERE id=1 AND import_job IS NOT NULL)
BEGIN
 INSERT INTO issue_recurrence_boundaries VALUES(NEW.project,NEW.issue,NEW.boundary_seq,EXISTS(SELECT 1 FROM events WHERE project=NEW.project AND issue=NEW.issue AND release_seq=NEW.boundary_seq))
 ON CONFLICT(issue) DO UPDATE SET boundary_seq=excluded.boundary_seq,seen_at_resolution=excluded.seen_at_resolution;
END;

CREATE TRIGGER issue_suppression_occurrence AFTER UPDATE OF count ON issues
WHEN NEW.count>OLD.count AND EXISTS(SELECT 1 FROM audit_context WHERE action IN ('capture.native','capture.sentry','capture.otlp'))
BEGIN
 UPDATE issue_suppressions SET observed_count=observed_count+NEW.count-OLD.count
 WHERE project=NEW.project AND issue=NEW.id AND historical=0 AND state='active';
END;
INSERT OR IGNORE INTO issue_recurrence_boundaries
 SELECT r.project,r.issue,COALESCE(r.boundary_seq,i.resolved_seq),EXISTS(SELECT 1 FROM events e
  WHERE e.project=r.project AND e.issue=r.issue AND e.release_seq=COALESCE(r.boundary_seq,i.resolved_seq) AND e.received<=r.updated)
 FROM issue_resolutions r JOIN issues i ON i.project=r.project AND i.id=r.issue WHERE i.state='resolved' AND r.mode IN ('current','next','named');

CREATE TRIGGER restored_work_commit AFTER UPDATE OF import_job ON rer_portability_state
 WHEN OLD.import_job IS NOT NULL AND NEW.import_job IS NULL AND OLD.applying=1 BEGIN
 INSERT OR IGNORE INTO restored_work SELECT project,'repair',id FROM repairs;
 INSERT OR IGNORE INTO restored_work SELECT project,'run',id FROM reproducer_runs;
 INSERT OR IGNORE INTO restored_work SELECT project,'fix',id FROM fix_workflows;
END

